#include "pipeline/local_credits.hpp"
#include <iostream>
#include <type_traits>
#include <utility>
unsigned lost(const mhgp8::CreditPlan& p) {
  const auto points=p.rectangle().points();
  unsigned result=0;
  for (std::size_t a=0;a<2;++a) for (std::size_t b=2;b<4;++b) {
    unsigned inside=0;
    for (std::size_t z=0;z<4;++z) if (z!=a && z!=b) {
      long long h=0;
      for(std::size_t k=0;k<3;++k) h+=(static_cast<long long>(points[z][k])-points[a][k])*(static_cast<long long>(points[b][k])-points[z][k]);
      inside+=static_cast<unsigned>(h>0);
    }
    result+=static_cast<unsigned>(inside==0 && !p.keeps(a,b));
  }
  return result;
}
int main() {
  static_assert(!std::is_copy_constructible_v<mhgp8::PreparedRectangle>);
  static_assert(!std::is_copy_assignable_v<mhgp8::PreparedRectangle>);
  static_assert(!std::is_move_constructible_v<mhgp8::PreparedRectangle>);
  static_assert(!std::is_move_assignable_v<mhgp8::PreparedRectangle>);
  mhgp8::RectangleInput input;
  input.points={{0,0,0},{1,0,0},{100,0,0},{101,0,0}};
  input.a={0,2}; input.b={2,4};
  mhgp8::Point3* alias=input.points.data();
  const auto rectangle=mhgp8::prepare_rectangle(std::move(input),1,8);
  if (alias!=rectangle->points().data()) return 3;
  const auto plan=mhgp8::make_credit_plan(rectangle,mhgp8::Lane::Q2,mhgp8::Strategy::DualBlocks);
  if (plan.candidate_pairs()!=1 || lost(plan)!=0) return 4;
  alias[0]={0,0,0}; alias[1]={0,10,0}; alias[2]={1000,0,0}; alias[3]={1000,10,0};
  if (lost(plan)!=3) return 5;
  std::cout << "{\"status\":\"observed_input_buffer_alias\",\"same_buffer\":true,\"closed_special_members\":4,\"lost_q2_pairs\":3}\n";
}
